llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Pamatolol, a close aryloxypropanolamine analogue with a para-substituted phenyl and secondary amino alcohol, had absolute oral bioavailability of 64.9–103.5% in healthy subjects after a 50 mg oral dose versus IV, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Diacetolol, sharing the aryloxypropanolamine core and para-substituted phenyl, had mean absolute oral bioavailability of 0.426 ± 0.068 at 800 mg, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pindolol, a beta-blocker with the same hydroxypropoxyamine pharmacophore, had absolute oral bioavailability of 86 ± 7% in patients without renal impairment, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bufuralol, containing the tert-butylamino-hydroxypropoxy motif identical to the query, showed fractional systemic availability of 0.52–0.83 in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Practolol, another para-substituted aryloxypropanolamine beta-blocker, had reported absolute oral bioavailability of 90–100%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable analogues are beta-blocker-like aryloxypropanolamines with measured absolute oral bioavailability well above 20% (approximately 42–100%). Although rifampin co-treatment could reduce bioavailability through enzyme/transporter induction, the high baseline F values of close analogues make it more likely that F remains ≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule under rifampin co-treatment.",
    "No rifampin interaction data for the closest structural analogues.",
    "The metabolic and transporter pathways of the query are not experimentally defined, so the magnitude of any rifampin effect is uncertain.",
    "No low-bioavailability analogue evidence was available to anchor a negative prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

